-    const float step_ratio = 2.0; // geometric sample distribution
-    const float z_tolerance = 10.0; // assumed thickness in blocks
-
-    vec3 ray_dir_screen = normalize(
-        view_to_screen_space(
-            projection_matrix,
-            ray_origin_view + ray_dir_view,
-            true
-        )
-        - ray_origin_screen
-    );
