-    a = display_eotf(a);
-    b = display_eotf(b);
-    c = display_eotf(c);
-    d = display_eotf(d);
-    e = display_eotf(e);
-    f = display_eotf(f);
-    g = display_eotf(g);
-    h = display_eotf(h);
-    i = display_eotf(i);
