+    rgb_post.r = segmented_spline_c9_fwd(rgb_pre.r);
+    rgb_post.g = segmented_spline_c9_fwd(rgb_pre.g);
+    rgb_post.b = segmented_spline_c9_fwd(rgb_pre.b);
