+float get_handheld_light_falloff(vec3 scene_pos, float ao) {
+    float falloff = lift(rcp(dot(scene_pos, scene_pos) + 1.0), 3.0);
+    return falloff * mix(ao, 1.0, falloff * falloff)
+        * 1.00;
