+    const float ripple_frequency = 0.3;
+    const float ripple_speed = 0.1;
+    const vec2 ripple_dir_0 = vec2(3.0, 4.0) / 5.0;
+    const vec2 ripple_dir_1 = vec2(-5.0, -12.0) / 13.0;
