+    float ripple1 = get_ripple_height(world_pos.xz + vec2(h, 0.0));
+    float ripple2 = get_ripple_height(world_pos.xz + vec2(0.0, h));
+    vec3 ripple_normal = vec3(ripple1 - ripple0, ripple2 - ripple0, h);
