+        mix(step_count_horizon,
+            step_count_zenith,
+            dampen(abs(ray_direction_world.y)))
+    );
+
+    // Calculate ray start and ray end
+
+    float r = planet_radius + eyeAltitude * cloudsScale;
+    vec2 dists = intersect_spherical_shell(
