+    vec4 noise = hash4(coord);
+
+    float star = linear_step(star_threshold, 1.0, noise.x);
+    star = pow16(star) * starsIntensity;
+
+    float temp = mix(min_temp, max_temp, noise.y);
+    vec3 color = blackbody(temp);
