+    float twinkle_amount = noise.z;
+    float twinkle_offset = tau * noise.w;
+    star *= 1.0
+        - twinkle_amount
+            * cos(frameTimeCounter * twinkle_speed + twinkle_offset);
+
+    return star * color;
+}
